'use server'

import { revalidateTag } from 'next/cache'
import fs from 'node:fs/promises'
import path from 'node:path'

// Helper to get posts file path
const postsFilePath = path.join(process.cwd(), 'posts.json')

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string
  const content = formData.get('content') as string

  if (!title || !content) {
    throw new Error('Title and content are required')
  }

  const newPost = {
    id: Date.now().toString(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  // Read existing posts
  const fileContent = await fs.readFile(postsFilePath, 'utf-8')
  const posts = JSON.parse(fileContent)

  // Add new post
  posts.push(newPost)

  // Save posts
  await fs.writeFile(postsFilePath, JSON.stringify(posts, null, 2))

  // Invalidate the cache tag "posts"
  // This ensures that the next fetch for data tagged with "posts" will skip the cache
  // and fetch fresh data from the source (in this case, the file).
  revalidateTag('posts')
}

import { unstable_cache } from 'next/cache'
import fs from 'node:fs/promises'
import path from 'node:path'

const postsFilePath = path.join(process.cwd(), 'posts.json')

export const getPosts = unstable_cache(
  async () => {
    try {
      const fileContent = await fs.readFile(postsFilePath, 'utf-8')
      return JSON.parse(fileContent)
    } catch (error) {
      // If file doesn't exist or is empty, return empty array
      return []
    }
  },
  ['posts'], // Key parts for cache
  { tags: ['posts'] } // Revalidation tags
)

